// Pixel load event listener
jQuery(document).on("pmw:load-pixels", () => {

	if (wpmDataLayer?.pixels?.linkedin?.partner_id && !wpmDataLayer?.pixels?.linkedin?.loaded) {
		if (wpm.consent.canPixelBeFired("marketing", "LinkedIn")) wpm.load_linkedin_pixel()
	}
})

// view_content event
jQuery(document).on("pmw:browser:view-item", (event, payload) => {

	try {
		if(wpm.canNotFireLinktrk()) return

		const linkedinData = payload.pixels?.linkedin;
		if (!linkedinData) return;

		window.lintrk("track", linkedinData)
		pmw.console.log("LinkedIn: view_content event sent", linkedinData)

	} catch (e) {
		console.error(e)
	}
})

